4: * Replaces unstructured console.log/warn/error across the server.
10: * - Sentry integration for error-level logs
14: * This eliminates 387+ TS2769 errors from pino v10's strict generics.
24: *   logger.info("message", { data })   — used throughout codebase
25: *   logger.info({ data }, "message")   — pino's canonical form
26: *   logger.info("message")             — simple string
27: *   logger.info({ data })              — object only
41:  debug: FlexibleLogMethod;
42:  info: FlexibleLogMethod;
43:  warn: FlexibleLogMethod;
44:  error: FlexibleLogMethod;
111:  level: process.env.LOG_LEVEL || (isDev ? 'debug' : 'info'),
201:  | 'error-contracts'
282: *   log.info({ eventId: 'evt_123' }, 'Processing webhook event');
283: *   log.error({ err }, 'Webhook processing failed');
284: *   log.info('Simple message');
285: *   log.warn('Message with data', { key: 'value' });
298: *   log.info('Processing request');
310: * Use for any data that might contain user information.
312:export function safeLog(logger: GravitoLogger, level: 'info' | 'warn' | 'error' | 'debug', data: Record<string, unknown>, message: string) {
---
  blockedBy: "enforcement" | "perception" | "evaluator" | "red_team";
  riskLevel?: string;
}): Promise<void> {
  try {
    const db = await getDb();
    if (!db) return;
    await db.insert(governanceFeedback).values({
      sectionId: params.sectionId,
      attemptNumber: params.attemptNumber,
      originalOutput: params.originalOutput,
      blockedReasons: JSON.stringify(params.blockedReasons),
      blockedBy: params.blockedBy,
      riskLevel: params.riskLevel || "unknown",
    });
  } catch (err) {
    logger.warn("[JetEngine] Failed to record block:", err);
  }
}

/**
 * Record what the fix was after a block — the version that eventually passed.
 */
export async function recordFix(sectionId: string, fixedOutput: string): Promise<void> {
  try {
    const db = await getDb();
    if (!db) return;
    // Update the most recent unfixed block for this section
    const recent = await db
      .select()
      .from(governanceFeedback)
      .where(and(eq(governanceFeedback.sectionId, sectionId)))
      .orderBy(desc(governanceFeedback.createdAt))
      .limit(1);

